const resposta = $input.first().json;

const bloco = resposta.content.find(b => b.type === 'text');

if (!bloco) {
  throw new Error('Resposta sem texto. stop_reason: ' + resposta.stop_reason);
}

const limpo = bloco.text.replace(/```json|```/g, '').trim();
return [{ json: JSON.parse(limpo) }];

